#!/bin/sh
# Fetch the images of docker-compose.yaml by digest into images/ (generated by hydo compose; hydo-build
# never pulls). Needs hydo-fetch-image (it comes with hydo) and network access, once.
set -eu
cd "$(dirname "$0")"
F=${HYDO_FETCH_IMAGE:-$(command -v hydo-fetch-image || true)}
[ -n "$F" ] || { echo "fetch-images.sh: hydo-fetch-image not found (put hydo's bin directory on PATH, or set HYDO_FETCH_IMAGE)" >&2; exit 1; }
mkdir -p images
[ -e images/ghcr.io-tursodatabase-libsql-server-v0.24.33-arm64-oci ] || "$F" ghcr.io/tursodatabase/libsql-server sha256:d2184b6faf4ccea9b480180467279d682e7aca9217cd8234655885dabfac8a23 ghcr.io/tursodatabase/libsql-server:v0.24.33 images/ghcr.io-tursodatabase-libsql-server-v0.24.33-arm64-oci
[ -f images/ghcr.io-tursodatabase-libsql-server-v0.24.33-amd64.docker.tar ] || "$F" ghcr.io/tursodatabase/libsql-server sha256:756fb4d34447cfa9507dceb3a8e680435d7f2173e2aa680f44a1329e774f7d31 ghcr.io/tursodatabase/libsql-server:v0.24.33 images/ghcr.io-tursodatabase-libsql-server-v0.24.33-amd64.docker.tar
ls -ld images/ghcr.io-tursodatabase-libsql-server-v0.24.33-amd64.docker.tar images/ghcr.io-tursodatabase-libsql-server-v0.24.33-arm64-oci
